const b = $input.first().json.body || $input.first().json || {};
const platform = String(b.platform || 'discord').toLowerCase();
const target = String(b.target || '');
const message = String(b.message || '');
const brand = $env.BRAND_NAME || 'Tradesejon';
if (!target || !message) return [{ json: { ok: false, delivered: false, error: 'Missing target or message payload' } }];

if (platform === 'discord') {
  const token = $env.DISCORD_BOT_TOKEN;
  if (!token) return [{ json: { ok: false, delivered: false, error: 'DISCORD_BOT_TOKEN not configured' } }];
  const dmRes = await fetch('https://discord.com/api/v10/users/@me/channels', {
    method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ recipient_id: target })
  });
  const dmData = await dmRes.json();
  if (!dmRes.ok || !dmData.id) return [{ json: { ok: false, delivered: false, error: 'Discord DM open failed', details: dmData } }];
  const msgRes = await fetch(`https://discord.com/api/v10/channels/${dmData.id}/messages`, {
    method: 'POST', headers: { 'Authorization': `Bot ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ content: message })
  });
  const msgData = await msgRes.json();
  if (!msgRes.ok || !msgData.id) return [{ json: { ok: false, delivered: false, error: 'Discord rejected delivery', details: msgData } }];
  return [{ json: { ok: true, delivered: true, platform: 'discord', messageId: msgData.id } }];
}

if (platform === 'telegram') {
  const token = $env.TELEGRAM_CEO_BOT_TOKEN;
  if (!token) return [{ json: { ok: false, delivered: false, error: 'TELEGRAM_CEO_BOT_TOKEN not configured' } }];
  const tgRes = await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: target, text: message, parse_mode: 'HTML' })
  });
  const tgData = await tgRes.json();
  if (!tgData.ok) return [{ json: { ok: false, delivered: false, error: 'Telegram rejected delivery', details: tgData } }];
  return [{ json: { ok: true, delivered: true, platform: 'telegram', messageId: tgData.result.message_id } }];
}

if (platform === 'email') {
  const resendKey = $env.RESEND_API_KEY;
  if (!resendKey) return [{ json: { ok: false, delivered: false, error: 'RESEND_API_KEY not configured' } }];
  const emRes = await fetch('https://api.resend.com/emails', {
    method: 'POST', headers: { 'Authorization': `Bearer ${resendKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      from: $env.RESEND_FROM_EMAIL || 'vip@yourdomain.com',
      to: [target],
      subject: String(b.subject || `${brand} Executive Update`),
      html: `<p>${message.replace(/\n/g, '<br>')}</p>`
    })
  });
  const emData = await emRes.json();
  if (!emRes.ok || !emData.id) return [{ json: { ok: false, delivered: false, error: 'Email API rejected delivery', details: emData } }];
  return [{ json: { ok: true, delivered: true, platform: 'email', messageId: emData.id } }];
}

return [{ json: { ok: false, delivered: false, error: `Unsupported platform: ${platform}` } }];
